use std::fmt;
use uuid::Uuid;

/// Canonical identity of an administrator.
///
/// The UUID is generated by an application or infrastructure boundary and is
/// injected into the domain. This type intentionally has no OS-backed
/// generation method.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AdminUserId(Uuid);

impl AdminUserId {
    pub const fn from_uuid(value: Uuid) -> Self {
        Self(value)
    }

    pub const fn as_uuid(self) -> Uuid {
        self.0
    }
}

impl From<Uuid> for AdminUserId {
    fn from(value: Uuid) -> Self {
        Self::from_uuid(value)
    }
}

impl From<AdminUserId> for Uuid {
    fn from(value: AdminUserId) -> Self {
        value.as_uuid()
    }
}

impl fmt::Display for AdminUserId {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(formatter)
    }
}

/// The smallest actor identity needed before authentication and RBAC exist.
///
/// More actor kinds can be added when their ownership and authorization
/// semantics are implemented; this enum is not a permission model.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ActorIdentity {
    Administrator(AdminUserId),
}

impl ActorIdentity {
    pub const fn administrator(user_id: AdminUserId) -> Self {
        Self::Administrator(user_id)
    }

    pub const fn admin_user_id(self) -> AdminUserId {
        match self {
            Self::Administrator(user_id) => user_id,
        }
    }
}

#[cfg(test)]
mod tests {
    use uuid::Uuid;

    use super::{ActorIdentity, AdminUserId};

    #[test]
    fn admin_user_id_round_trips_as_a_canonical_uuid() {
        let uuid = Uuid::parse_str("019fe250-3bc5-7cf0-b3d2-0728c077a930")
            .expect("fixture UUID should be valid");
        let user_id = AdminUserId::from_uuid(uuid);

        assert_eq!(user_id.as_uuid(), uuid);
        assert_eq!(user_id.to_string(), "019fe250-3bc5-7cf0-b3d2-0728c077a930");
        assert_eq!(Uuid::from(user_id), uuid);
    }

    #[test]
    fn actor_identity_keeps_administrator_ownership_explicit() {
        let user_id = AdminUserId::from_uuid(
            Uuid::parse_str("019fe250-3bc5-7cf0-b3d2-0728c077a930")
                .expect("fixture UUID should be valid"),
        );
        let actor = ActorIdentity::administrator(user_id);

        assert_eq!(actor, ActorIdentity::Administrator(user_id));
        assert_eq!(actor.admin_user_id(), user_id);
    }
}
